import React from 'react';
import { MapPin, ThumbsUp, MessageCircle, Clock } from 'lucide-react';

const Home = () => {
  const issues = [
    {
      id: 1,
      title: 'Large pothole on MG Road',
      description: 'Deep pothole causing traffic issues and vehicle damage',
      category: 'Potholes',
      status: 'Pending',
      location: 'MG Road, Sector 14',
      upvotes: 23,
      comments: 5,
      timeAgo: '2 hours ago',
      reporter: 'Priya Sharma'
    },
    {
      id: 2,
      title: 'Broken streetlight near park',
      description: 'Street light has been non-functional for a week, creating safety concerns',
      category: 'Streetlights',
      status: 'In Progress',
      location: 'Central Park, Block A',
      upvotes: 18,
      comments: 3,
      timeAgo: '1 day ago',
      reporter: 'Rajesh Kumar'
    },
    {
      id: 3,
      title: 'Garbage collection missed',
      description: 'Garbage has not been collected for 3 days in residential area',
      category: 'Garbage',
      status: 'Resolved',
      location: 'Residential Complex, Phase 2',
      upvotes: 31,
      comments: 8,
      timeAgo: '3 days ago',
      reporter: 'Anita Patel'
    }
  ];

  const getStatusColor = (status) => {
    switch (status) {
      case 'Pending': return 'var(--sun-yellow)';
      case 'In Progress': return 'var(--civic-orange)';
      case 'Resolved': return 'var(--soft-lime)';
      default: return 'var(--urban-gray)';
    }
  };

  return (
    <div className="home-page">
      <div className="container">
        <div className="page-header">
          <h1>🏠 Community Feed</h1>
          <p>Latest civic issues in your area</p>
        </div>

        <div className="filters">
          <button className="filter-btn active">All Issues</button>
          <button className="filter-btn">Potholes</button>
          <button className="filter-btn">Streetlights</button>
          <button className="filter-btn">Garbage</button>
          <button className="filter-btn">Water Leaks</button>
        </div>

        <div className="issues-grid">
          {issues.map((issue) => (
            <div key={issue.id} className="issue-card fade-in">
              <div className="issue-header">
                <div className="issue-meta">
                  <span className="reporter">👤 {issue.reporter}</span>
                  <span className="time">
                    <Clock size={14} />
                    {issue.timeAgo}
                  </span>
                </div>
                <span 
                  className="status-badge"
                  style={{ backgroundColor: getStatusColor(issue.status) }}
                >
                  {issue.status}
                </span>
              </div>

              <h3 className="issue-title">{issue.title}</h3>
              <p className="issue-description">{issue.description}</p>

              <div className="issue-location">
                <MapPin size={16} />
                <span>{issue.location}</span>
              </div>

              <div className="issue-actions">
                <button className="action-btn">
                  <ThumbsUp size={16} />
                  <span>{issue.upvotes}</span>
                </button>
                <button className="action-btn">
                  <MessageCircle size={16} />
                  <span>{issue.comments}</span>
                </button>
                <span className="category-tag">{issue.category}</span>
              </div>
            </div>
          ))}
        </div>
      </div>

      <style jsx>{`
        .home-page {
          padding: var(--spacing-xl) 0;
        }

        .page-header {
          text-align: center;
          margin-bottom: var(--spacing-xl);
        }

        .page-header h1 {
          color: var(--civic-blue);
          margin-bottom: var(--spacing-sm);
        }

        .page-header p {
          color: var(--text-secondary);
          font-size: 1.1rem;
        }

        .filters {
          display: flex;
          gap: var(--spacing-sm);
          margin-bottom: var(--spacing-xl);
          overflow-x: auto;
          padding-bottom: var(--spacing-sm);
        }

        .filter-btn {
          padding: var(--spacing-sm) var(--spacing-md);
          border: 2px solid var(--civic-blue);
          background: transparent;
          color: var(--civic-blue);
          border-radius: var(--radius-xl);
          font-weight: 500;
          cursor: pointer;
          transition: all 0.2s ease;
          white-space: nowrap;
        }

        .filter-btn:hover,
        .filter-btn.active {
          background: var(--civic-blue);
          color: var(--text-light);
        }

        .issues-grid {
          display: grid;
          gap: var(--spacing-lg);
          grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
        }

        .issue-card {
          background: var(--white);
          border-radius: var(--radius-md);
          box-shadow: var(--shadow-sm);
          padding: var(--spacing-lg);
          transition: all 0.2s ease;
        }

        .issue-card:hover {
          box-shadow: var(--shadow-md);
          transform: translateY(-2px);
        }

        .issue-header {
          display: flex;
          justify-content: space-between;
          align-items: flex-start;
          margin-bottom: var(--spacing-md);
        }

        .issue-meta {
          display: flex;
          flex-direction: column;
          gap: var(--spacing-xs);
        }

        .reporter {
          font-size: 0.875rem;
          color: var(--text-secondary);
          font-weight: 500;
        }

        .time {
          display: flex;
          align-items: center;
          gap: var(--spacing-xs);
          font-size: 0.75rem;
          color: var(--text-secondary);
        }

        .status-badge {
          padding: var(--spacing-xs) var(--spacing-sm);
          border-radius: var(--radius-sm);
          font-size: 0.75rem;
          font-weight: 600;
          color: var(--text-light);
          text-transform: uppercase;
        }

        .issue-title {
          color: var(--text-primary);
          margin-bottom: var(--spacing-sm);
          font-size: 1.1rem;
        }

        .issue-description {
          color: var(--text-secondary);
          line-height: 1.5;
          margin-bottom: var(--spacing-md);
        }

        .issue-location {
          display: flex;
          align-items: center;
          gap: var(--spacing-xs);
          color: var(--text-secondary);
          font-size: 0.875rem;
          margin-bottom: var(--spacing-md);
        }

        .issue-actions {
          display: flex;
          align-items: center;
          gap: var(--spacing-md);
        }

        .action-btn {
          display: flex;
          align-items: center;
          gap: var(--spacing-xs);
          padding: var(--spacing-xs) var(--spacing-sm);
          border: 1px solid var(--emerald-green);
          background: transparent;
          color: var(--emerald-green);
          border-radius: var(--radius-sm);
          cursor: pointer;
          transition: all 0.2s ease;
          font-size: 0.875rem;
        }

        .action-btn:hover {
          background: var(--emerald-green);
          color: var(--text-light);
        }

        .category-tag {
          margin-left: auto;
          padding: var(--spacing-xs) var(--spacing-sm);
          background: rgba(0, 119, 182, 0.1);
          color: var(--civic-blue);
          border-radius: var(--radius-sm);
          font-size: 0.75rem;
          font-weight: 500;
        }

        @media (max-width: 768px) {
          .issues-grid {
            grid-template-columns: 1fr;
          }
          
          .filters {
            justify-content: center;
          }
        }
      `}</style>
    </div>
  );
};

export default Home;
